import os, requests, urllib.parse, json
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
headers={'x-api-key':key}
tid='toolshed.g2.bx.psu.edu/repos/iuc/plink/plink/1.90b6.21+galaxy2'
data=requests.get(url+'/api/tools/'+urllib.parse.quote(tid, safe='')+'/build',headers=headers,params={'history_id':'bbd44e69cb8906b57393a8b551ea9ef2'},timeout=30).json()

def walk(inp, indent=0):
    pad='  '*indent
    print(pad+f\"{inp.get('model_class')} name={inp.get('name')} type={inp.get('type')} value={inp.get('value')} default={inp.get('default_value')}\")
    if 'cases' in inp:
        print(pad+' cases: '+', '.join([c.get('value','') for c in inp['cases']]))
        for c in inp['cases']:
            if c.get('value') in ['ibd','vcf','Yes','No','']:
                print(pad+f\" WHEN {c.get('value')"'!r}")
                for child in c.get('"'inputs',[]): walk(child, indent+1)
    for child in inp.get('inputs',[]) or []:
        walk(child, indent+1)
for inp in data['inputs']:
    walk(inp)
PY"
